solution:
const money = {
  amount: 100,
  currency: "INR",
  [Symbol.toPrimitive](hint) {
    if (hint === "number") return this.amount
    return `${this.amount} ${this.currency}`
  }
}
return {
  asNumber: +money,
  asString: "" + money
}
